<script setup lang="ts">import { formatDate } from '~/utils/formatters'; definePageMeta({ middleware: 'auth' }); const route = useRoute(); const { find, updateStatus } = useEnrollments(); const id = Number(route.params.id); const { data: enrollment } = await useAsyncData(`enrollment-${id}`, () => find(id)); const saving = ref(false); async function changeStatus(status: string) { saving.value = true; try { enrollment.value = await updateStatus(id, status) } finally { saving.value = false } }</script>
<template><div v-if="enrollment" class="page-shell"><PageHeader :title="`${enrollment.student?.first_name} ${enrollment.student?.last_name}`" :description="enrollment.course_offering?.course?.course_title"><template #actions><StatusBadge :status="enrollment.status" /></template></PageHeader><BaseCard><dl class="grid gap-5 sm:grid-cols-3"><div><dt class="text-sm text-slate-500">Course</dt><dd class="font-semibold">{{ enrollment.course_offering?.course?.course_code }}</dd></div><div><dt class="text-sm text-slate-500">Enrolled</dt><dd class="font-semibold">{{ formatDate(enrollment.enrollment_date) }}</dd></div><div><dt class="text-sm text-slate-500">Section</dt><dd class="font-semibold">{{ enrollment.course_offering?.section }}</dd></div></dl><div v-if="enrollment.status === 'enrolled'" class="mt-6 flex gap-3"><BaseButton variant="secondary" :loading="saving" @click="changeStatus('dropped')">Mark dropped</BaseButton><BaseButton variant="secondary" :loading="saving" @click="changeStatus('withdrawn')">Mark withdrawn</BaseButton><BaseButton :loading="saving" @click="changeStatus('completed')">Mark completed</BaseButton></div></BaseCard></div></template>
